<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileBirthdateVO;

trait UserProfileBirthdateAccessor
{
    private ?UserProfileBirthdateVO $_birthdate = null;
    public function getBirthdate(): ?string
    {
        return $this->_birthdate?->value();
    }
    public function birthdate(): ?UserProfileBirthdateVO
    {
        return $this->_birthdate;
    }
    public function isBirthdateChanged(?self $original = null): bool
    {
        return null !== $this->_birthdate && !$this->_birthdate->equals($original?->_birthdate);
    }
    public function withBirthdate(UserProfileBirthdateVO|string|null $birthdate): self
    {
        $copy = clone $this;
        $copy->_birthdate = UserProfileBirthdateVO::from($birthdate);
        return $copy;
    }
}
